# form input grid and stamp template independently to each 8-connected component; find placements maximizing seed inclusion
import itertools
base=[(0,2),(1,1),(1,3),(2,0),(2,1),(2,3)]
# reset g from original objs points
n=30; inp=[[1]*n for _ in range(n)]
for c,pts in objs.items():
 for r,x in pts: inp[r][x]=c
# components 8-connected per color
out=[row[:] for row in inp]
for color, pts in objs.items():
 if color==4: continue
 rem=set(pts); comps=[]
 while rem:
  stack=[rem.pop()]; comp=set(stack)
  while stack:
   r,x=stack.pop()
   for q in list(rem):
    if max(abs(q[0]-r),abs(q[1]-x))<=1:
     rem.remove(q);stack.append(q);comp.add(q)
  comps.append(comp)
 for comp in comps:
  best=None
  for k in range(4):
   p=base
   for _ in range(k):p=[(x,-r) for r,x in p]
   for flip in [0,1]:
    q=[(r,-x if flip else x) for r,x in p]; mr=min(r for r,x in q);mc=min(x for r,x in q);q=[(r-mr,x-mc) for r,x in q]
    for ar in range(n):
     for ac in range(n):
      cov={(ar+r,ac+x) for r,x in q}
      if max(r for r,x in cov)>=n or max(x for r,x in cov)>=n:continue
      score=len(comp&cov)
      if score==len(comp) and (best is None or len(cov)<len(best)):
       best=cov
  if best:
   for r,x in best:out[r][x]=color
  else: print('no fit',color,comp)
